import { useNavigate } from 'react-router-dom';
import { getLocalData, removeLocalData } from '../utils/storage';

function Header() {
  const navigate = useNavigate();
  const currentUser = getLocalData('currentUser');

  const userName = currentUser ? currentUser.name || currentUser.username || 'User' : 'User';
  const firstLetter = userName.charAt(0).toUpperCase();

  function handleLogout() {
    removeLocalData('currentUser');
    navigate('/login');
  }

  return (
    <div style={{
      backgroundColor: '#fff',
      borderBottom: '1px solid #ddd',
      padding: '10px 20px',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'space-between'
    }}>
      <h5 style={{ margin: 0, color: '#2563eb', fontWeight: 'bold' }}>
        HRM System
      </h5>

      <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
        {/* Avatar chữ cái đầu */}
        <div style={{
          width: '32px',
          height: '32px',
          borderRadius: '50%',
          backgroundColor: '#2563eb',
          color: '#fff',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          fontWeight: 'bold',
          fontSize: '14px'
        }}>
          {firstLetter}
        </div>

        <span style={{ fontSize: '14px', color: '#333' }}>{userName}</span>

        <button
          onClick={handleLogout}
          style={{
            padding: '5px 12px',
            fontSize: '13px',
            backgroundColor: '#fff',
            border: '1px solid #ccc',
            borderRadius: '4px',
            cursor: 'pointer',
            color: '#555'
          }}
        >
          Đăng xuất
        </button>
      </div>
    </div>
  );
}

export default Header;
